#!/bin/bash
#
# Brings Drupal core and sites/all (contrib modules, themes, libraries) from
# production into .local/docroot with rsync. Read-only on the server.
#
# Not copied, on purpose:
#   sites/default/settings.php   production credentials; the local one is
#                                generated by scripts/local/gen-settings.sh
#   sites/default/files          ~850 MB of uploads; the site works without them.
#                                One exception IS copied: files/mailsystem/,
#                                where the mailsystem module keeps the generated
#                                class HTMLMailSystem__SmtpMailSystem. Without
#                                that file the class named in 'mail_system'
#                                cannot be loaded and the module resets the
#                                variable on the first bootstrap.
#   sites/all/modules/myapi      mounted live from this repository
#   manual/                      built and published by scripts/local/deploy-manual.sh
#   payphone/, .well-known/      payment gateway glue and ACME challenges
#
#   --yes   skip the confirmation prompt

set -euo pipefail

. "$(dirname "$0")/lib.sh"
[ "${1:-}" = "--yes" ] && MYAPI_LOCAL_ASSUME_YES=1
load_prod_target
require_free_mb 2048
confirm_prod "Se va a copiar el core y sites/all de producción a $DOCROOT (rsync, unos 100 MB)."

echo "Copiando el core y sites/all desde producción..."
rsync -az --delete --stats \
  -e "ssh -i $PROD_KEY -o BatchMode=yes" \
  --exclude='/sites/default/settings.php' \
  --include='/sites/default/files/mailsystem/' \
  --include='/sites/default/files/mailsystem/*' \
  --exclude='/sites/default/files/*' \
  --exclude='/sites/all/modules/myapi/' \
  --exclude='/sites/all/modules/myapi_test/' \
  --exclude='/manual/' \
  --exclude='/payphone/' \
  --exclude='/.well-known/' \
  --exclude='/limits-check.php' \
  "$PROD_SERVER:/var/www/html/" "$DOCROOT/" | tail -4

# sites/default arrives read-only (555), as Drupal leaves it on the server.
chmod u+w "$DOCROOT/sites/default"

# Mount points and writable directories the containers expect.
mkdir -p "$DOCROOT/sites/all/modules/myapi" "$DOCROOT/sites/default/files"

"$LOCAL_SCRIPTS_DIR/gen-settings.sh"

echo "Código listo en $DOCROOT ($(du -sh "$DOCROOT" | cut -f1))."
